def choose_move(observation):
    def clamp_step(v):
        return 0 if v == 0 else (1 if v > 0 else -1)

    def safe_pos(obj, default=(0, 0)):
        if isinstance(obj, (list, tuple)) and len(obj) >= 2:
            return obj[0], obj[1]
        return default

    def step_toward(a, b):
        ax, ay = a
        bx, by = b
        return [clamp_step(bx - ax), clamp_step(by - ay)]

    def step_away(a, b):
        ax, ay = a
        bx, by = b
        return [clamp_step(ax - bx), clamp_step(ay - by)]

    def manhattan(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    env = observation.get("environment_name", "resource_collection")
    sx, sy = safe_pos(observation.get("self_position"))
    ox, oy = safe_pos(observation.get("opponent_position"))

    w = observation.get("grid_width", 0)
    h = observation.get("grid_height", 0)

    if env == "pursuit_evasion":
        role = observation.get("self_role", "pursuer")
        if role == "pursuer":
            return step_toward((sx, sy), (ox, oy))

        corners = []
        if w and h:
            corners = [(0, 0), (0, h - 1), (w - 1, 0), (w - 1, h - 1)]
        if corners:
            target = max(corners, key=lambda p: manhattan(p, (ox, oy)) - manhattan(p, (sx, sy)) * 0.1)
            return step_toward((sx, sy), target)
        return step_away((sx, sy), (ox, oy))

    if env == "territory_control":
        targets = observation.get("unclaimed_cells") or observation.get("opponent_territory") or observation.get("frontier_cells") or []
        best = None
        best_score = None
        for t in targets:
            tx, ty = safe_pos(t, None)
            if tx is None:
                continue
            score = manhattan((sx, sy), (tx, ty))
            if best is None or score < best_score:
                best = (tx, ty)
                best_score = score
        if best is not None:
            return step_toward((sx, sy), best)

        # No obvious target: bias toward opponent if far, else avoid direct collision.
        if manhattan((sx, sy), (ox, oy)) <= 2:
            return step_away((sx, sy), (ox, oy))
        return step_toward((sx, sy), (ox, oy))

    resources = observation.get("resources") or observation.get("resource_positions") or []
    best = None
    best_score = None
    for r in resources:
        rx, ry = safe_pos(r, None)
        if rx is None:
            continue
        score = manhattan((sx, sy), (rx, ry))
        if best is None or score < best_score:
            best = (rx, ry)
            best_score = score

    if best is not None:
        # If opponent is much closer to the resource, slightly avoid direct contest.
        if manhattan((ox, oy), best) + 1 < manhattan((sx, sy), best):
            return step_away((sx, sy), (ox, oy))
        return step_toward((sx, sy), best)

    # Fallback: keep distance when threatened, otherwise pressure opponent.
    if manhattan((sx, sy), (ox, oy)) <= 1:
        return step_away((sx, sy), (ox, oy))
    return step_toward((sx, sy), (ox, oy))

